INSERT INTO public.enter_gauja_categories (key, name_lv, name_en, name_es, description_lv, description_en, description_es, icon_name, color_hex, sort_order) VALUES
 ('nature','Daba','Nature','Naturaleza','Meži, upes un dabas takas Gaujas ielejā.','Forests, rivers and nature trails in the Gauja valley.','Bosques, ríos y senderos naturales en el valle del Gauja.','deer','#4F6F19',1),
 ('history','Vēsture','History','Historia','Viduslaiku pilis, muižas un senās apmetnes.','Medieval castles, manors and ancient settlements.','Castillos medievales, mansiones y asentamientos antiguos.','tower','#D1701A',2),
 ('culture','Kultūra','Culture','Cultura','Amatniecība, muzeji un vietējie stāsti.','Crafts, museums and local stories.','Artesanía, museos e historias locales.','star','#51869D',3),
 ('action','Piedzīvojums','Action','Aventura','Aktīvi maršruti un piedzīvojumi brīvā dabā.','Active routes and outdoor adventures.','Rutas activas y aventuras al aire libre.','lightning','#F05366',4),
 ('getaround','Gauja Get-around','Gauja Get-around','Gauja Get-around','Transfēri un pārvietošanās Gaujas reģionā.','Transfers and getting around the Gauja region.','Traslados y desplazamientos por la región del Gauja.','horse','#6987B6',5)
ON CONFLICT (key) DO NOTHING;

-- ===== Guide profile =====
-- NOTE: biography text below is PLACEHOLDER copy — Ilze replaces it via /admin/profile.
INSERT INTO public.profile (
  full_name, role_lv, role_en, role_es,
  short_bio_lv, short_bio_en, short_bio_es,
  bio_lv, bio_en, bio_es,
  phone, email, whatsapp, languages_spoken, certifications, years_of_experience
)
SELECT
 'Ilze Gulbe',
 'Sertificēta gide un ekskursiju vadītāja','Certified guide and tour leader','Guía certificada y organizadora de excursiones',
 'Sertificēta gide ar vairāk nekā 10 gadu pieredzi Gaujas reģionā. Vadu ekskursijas, pārgājienus un piedāvāju privātos transfērus.',
 'Certified guide with over 10 years of experience in the Gauja region. I lead tours and hikes and offer private transfers.',
 'Guía certificada con más de 10 años de experiencia en la región del Gauja. Dirijo excursiones, caminatas y ofrezco traslados privados.',
 E'Esmu Ilze — dzimusi un augusi Gaujas krastos. Jau vairāk nekā desmit gadus vadu ekskursijas un pārgājienus Siguldā, Cēsīs, Līgatnē un Gaujas Nacionālajā parkā.\n\nMani visvairāk aizrauj stāsti, kas paliek aiz akmens mūriem un meža takām: kāpēc pils tika celta tieši šajā līkumā, kā smilšakmens klintis veidojušās tūkstošiem gadu, ko cilvēki šeit darīja pirms simts gadiem. Katrā maršrutā cenšos savienot ainavu ar konkrētu, pārbaudītu stāstu.\n\nStrādāju ar nelielām grupām — līdz astoņiem cilvēkiem ekskursijās un līdz desmit pārgājienos. Tā varam apstāties tur, kur gribas, pielāgot tempu un runāt, nevis klausīties skaļruni. Maršrutu vienmēr saskaņoju iepriekš: ar bērniem ejam vienu ceļu, ar pieredzējušiem gājējiem — citu.\n\nRunāju latviski, angliski, krieviski un spāniski. Ja plānojat dienu Gaujas ielejā un nezināt, ar ko sākt — uzrakstiet, un kopā saliksim maršrutu.',
 E'I am Ilze — born and raised on the banks of the Gauja. For more than ten years I have been leading tours and hikes in Sigulda, Cēsis, Līgatne and the Gauja National Park.\n\nWhat fascinates me most are the stories behind stone walls and forest trails: why a castle was built in this particular bend of the river, how the sandstone cliffs formed over thousands of years, what people did here a century ago.\n\nI work with small groups — up to eight people on tours and up to ten on hikes — so we can stop where we want and keep a comfortable pace. Routes are always agreed in advance.\n\nI speak Latvian, English, Russian and Spanish. If you are planning a day in the Gauja valley, write to me and we will put the route together.',
 E'Soy Ilze, nacida y criada a orillas del Gauja. Desde hace más de diez años dirijo excursiones y caminatas en Sigulda, Cēsis, Līgatne y el Parque Nacional del Gauja.\n\nLo que más me apasiona son las historias que se esconden tras los muros de piedra y los senderos del bosque: por qué se construyó un castillo justo en ese meandro, cómo se formaron los acantilados de arenisca.\n\nTrabajo con grupos pequeños —hasta ocho personas en excursiones y diez en caminatas—, así podemos parar donde queramos y mantener un ritmo cómodo.\n\nHablo letón, inglés, ruso y español. Si planea un día en el valle del Gauja, escríbame y armamos la ruta juntos.',
 '+371 29299354','ilze.gulbe@creatus.lv','+371 29299354',
 ARRAY['lv','en','ru','es'],
 '[{"name":"Sertificēta gide","year":2015,"issuer":"Latvijas Republika"}]'::jsonb,
 10
WHERE NOT EXISTS (SELECT 1 FROM public.profile);

