 is_active, sort_order
) VALUES
-- Excursions
('excursion','siguldas-pils-turaida','siguldas-pils-turaida','siguldas-pils-turaida',
 'Siguldas viduslaiku pils un Turaidas muzejrezervāts','Sigulda Medieval Castle and Turaida Museum Reserve','Castillo medieval de Sigulda y reserva museística de Turaida',
 'Divas Gaujas ielejas nozīmīgākās vietas vienā dienā — Livonijas ordeņa pilsdrupas un Turaidas sarkano ķieģeļu tornis.',
 'Two of the most important places in the Gauja valley in one day — the Livonian Order castle ruins and the red-brick Turaida tower.',
 'Dos de los lugares más importantes del valle del Gauja en un día: las ruinas de la Orden de Livonia y la torre de ladrillo rojo de Turaida.',
 E'Sākam Siguldas viduslaiku pilī, kuru 13. gadsimtā cēla Livonijas ordenis. Apstaigājam mūrus, uzkāpjam tornī un no skatu laukuma redzam visu Gaujas senleju.\n\nPēc tam dodamies uz Turaidas muzejrezervātu — 42 hektāru teritoriju ar sarkano ķieģeļu pili, baznīcu, Dainu kalnu un Turaidas Rozes kapu. Stāstu par Kaupo, par pils ugunsgrēku 1776. gadā un par to, kā tornis atkal tika atjaunots.\n\nMaršruts iet pa kājāmejamu teritoriju, tempu pielāgoju grupai. Ieejas biļetes objektos nav iekļautas cenā.',
 E'We start at Sigulda Medieval Castle, built by the Livonian Order in the 13th century. We walk the walls, climb the tower and take in the whole ancient Gauja valley from the viewing platform.\n\nThen we move to the Turaida Museum Reserve — 42 hectares with the red-brick castle, the church, Dainu Hill and the grave of the Rose of Turaida.\n\nThe route is walkable and the pace is adapted to the group. Entrance tickets are not included.',
 E'Comenzamos en el castillo medieval de Sigulda, construido por la Orden de Livonia en el siglo XIII. Recorremos los muros, subimos a la torre y contemplamos todo el valle antiguo del Gauja.\n\nDespués visitamos la reserva de Turaida: 42 hectáreas con el castillo de ladrillo rojo, la iglesia, la colina Dainu y la tumba de la Rosa de Turaida.\n\nEl ritmo se adapta al grupo. Las entradas no están incluidas.',
 240,45,true,2,8,ARRAY['history','culture']::public.enter_gauja_category[],NULL,'Sigulda',57.1626,24.8517,NULL,NULL,NULL,
 'Siguldas pils un Turaida — ekskursija ar gidi','Sigulda Castle and Turaida — guided tour','Castillo de Sigulda y Turaida — visita guiada',
 'Četru stundu ekskursija pa Siguldas viduslaiku pili un Turaidas muzejrezervātu ar sertificētu gidi.',
 'A four-hour guided tour of Sigulda Medieval Castle and the Turaida Museum Reserve with a certified guide.',
 'Excursión guiada de cuatro horas por el castillo medieval de Sigulda y la reserva de Turaida.',
 true,1),
('excursion','cesu-vecpilseta-pils','cesu-vecpilseta-pils','cesu-vecpilseta-pils',
 'Cēsu vecpilsēta un pils komplekss','Cēsis Old Town and Castle Complex','Casco antiguo de Cēsis y complejo del castillo',
 'Viduslaiku pilsdrupas ar tumšajiem pagrabiem, klusas bruģa ieliņas un vecpilsēta, ko var apstaigāt kājām.',
 'Medieval castle ruins with dark cellars, quiet cobbled streets and an old town you can walk end to end.',
 'Ruinas medievales con bodegas oscuras, calles empedradas y un casco antiguo que se recorre a pie.',
 E'Cēsis ir viena no retajām Latvijas pilsētām, kur viduslaiku plānojums saglabājies gandrīz nemainīgs. Sākam pils kompleksā — ar laternu ejam pa tumšajiem pagrabiem un kāpjam Rietumu tornī.\n\nTālāk pa vecpilsētu: Svētā Jāņa baznīca, Rožu laukums, Livonijas ordeņa mūri un amatnieku kvartāls. Stāstu par pilsētas lomu Hanzas tirdzniecībā un par 1577. gada notikumiem pilī.\n\nNoslēgumā — Cēsu pils parks. Maršruts pilnībā kājām, apmēram 3 km.',
 E'Cēsis is one of the few Latvian towns where the medieval layout survives almost unchanged. We start at the castle complex, walking the dark cellars with lanterns and climbing the Western Tower.\n\nThen the old town: St John''s Church, Rose Square, the Livonian Order walls and the craftsmen''s quarter.\n\nWe finish in the castle park. The route is entirely on foot, about 3 km.',
 E'Cēsis es una de las pocas ciudades letonas donde la traza medieval se conserva casi intacta. Empezamos en el castillo, recorriendo con farol las bodegas y subiendo a la Torre Oeste.\n\nLuego el casco antiguo: la iglesia de San Juan, la plaza de las Rosas y el barrio de artesanos.\n\nTerminamos en el parque del castillo. Unos 3 km a pie.',
 180,35,true,2,8,ARRAY['history','culture']::public.enter_gauja_category[],NULL,'Cēsis',57.3119,25.2749,NULL,NULL,NULL,
 'Cēsu vecpilsēta un pils — ekskursija','Cēsis Old Town and Castle — guided tour','Casco antiguo y castillo de Cēsis — visita',
 'Trīs stundu gājiens pa Cēsu viduslaiku pili un vecpilsētu sertificētas gides pavadībā.',
 'A three-hour walk through Cēsis medieval castle and old town with a certified guide.',
 'Paseo de tres horas por el castillo medieval y el casco antiguo de Cēsis con guía certificada.',
 true,2),
('excursion','ligatnes-ciemats-alas','ligatnes-ciemats-alas','ligatnes-ciemats-alas',
 'Līgatnes vēsturiskais ciemats un alu labirinti','Līgatne Historic Village and Cave Labyrinths','Aldea histórica de Līgatne y laberintos de cuevas',
 'Papīrfabrikas ciems ar alām smilšakmenī un meža takas Gaujas Nacionālā parka vidū.',
 'A paper mill village with sandstone cellars and forest trails in the middle of the Gauja National Park.',
 'Una aldea papelera con cuevas de arenisca y senderos en pleno Parque Nacional del Gauja.',
 E'Līgatne ir 19. gadsimta papīrfabrikas ciems, kas gandrīz nav mainījies: koka strādnieku mājas, meistaru villas, klubs un skola stāv tur, kur celtas.\n\nSmilšakmens kraujā izraktas alas — kādreiz pagrabi pārtikai, tagad viena no ciema zīmēm. Ejam gar tām, ieskatāmies un runājam par to, kā fabrika noteica visu dzīves ritmu.\n\nNoslēgumā nokāpjam pie Gaujas un, ja laiks atļauj, izmantojam vēsturisko prāmi.',
 E'Līgatne is a 19th-century paper mill village that has barely changed: wooden workers'' houses, foremen''s villas, the club and the school all stand where they were built.\n\nCaves dug into the sandstone cliff once served as food cellars and are now a symbol of the village.\n\nWe finish down by the Gauja and, weather permitting, use the historic cable ferry.',
 E'Līgatne es una aldea papelera del siglo XIX que apenas ha cambiado: casas de madera de los obreros, villas de los capataces, el club y la escuela.\n\nLas cuevas excavadas en la arenisca fueron despensas y hoy son el emblema del pueblo.\n\nTerminamos junto al Gauja y, si el tiempo lo permite, usamos el ferry histórico.',
 180,30,true,2,8,ARRAY['history','nature']::public.enter_gauja_category[],NULL,'Līgatne',57.2333,25.0500,NULL,NULL,NULL,
 'Līgatnes ciemats un alas — ekskursija','Līgatne village and caves — guided tour','Aldea de Līgatne y cuevas — visita',
 'Trīs stundu ekskursija pa Līgatnes papīrfabrikas ciematu, smilšakmens alām un Gaujas krastu.',
 'A three-hour guided tour of the Līgatne paper mill village, sandstone caves and the Gauja riverside.',
 'Excursión de tres horas por la aldea papelera de Līgatne, las cuevas de arenisca y la orilla del Gauja.',
 true,3),
('excursion','gaujas-nacionalais-parks','gaujas-nacionalais-parks','gaujas-nacionalais-parks',
 'Gaujas Nacionālais parks — dabas skaistums un vēsture','Gauja National Park — Nature and History','Parque Nacional del Gauja — naturaleza e historia',
 'Pilna diena parkā: smilšakmens klintis, senleja, pilis un skatu vietas vienā maršrutā.',
 'A full day in the park: sandstone cliffs, the ancient valley, castles and viewpoints in one route.',
 'Un día completo en el parque: acantilados de arenisca, el valle antiguo, castillos y miradores.',
 E'Sešu stundu maršruts pa Latvijas vecāko nacionālo parku. Sākam ar senlejas skatu vietām, tad ejam pie smilšakmens atsegumiem — Gūtmaņa alas, Velnalas un mazāk zināmām klintīm.\n\nDienas otrajā pusē pievēršamies vēsturei: pilsdrupas, muižas un stāsti par Gaujas lībiešiem.\n\nMaršrutu pielāgoju sezonai un laikapstākļiem. Ērti apavi obligāti, līdzi ņemam ūdeni un uzkodas.',
 E'A six-hour route through Latvia''s oldest national park. We start with valley viewpoints, then visit the sandstone outcrops — Gūtmanis Cave, Velnala and lesser-known cliffs.\n\nIn the afternoon we turn to history: castle ruins, manors and the story of the Gauja Livonians.\n\nThe route is adapted to the season. Sturdy shoes required.',
 E'Ruta de seis horas por el parque nacional más antiguo de Letonia: miradores, afloramientos de arenisca, la cueva de Gūtmanis y acantilados menos conocidos.\n\nPor la tarde, historia: ruinas, mansiones y los livonios del Gauja.\n\nLa ruta se adapta a la estación. Calzado adecuado imprescindible.',
 360,65,true,2,8,ARRAY['nature','history']::public.enter_gauja_category[],NULL,'Gaujas Nacionālais parks',57.2500,25.0000,NULL,NULL,NULL,
 'Gaujas Nacionālais parks — pilnas dienas ekskursija','Gauja National Park — full day guided tour','Parque Nacional del Gauja — excursión de día completo',
 'Sešu stundu ekskursija pa Gaujas Nacionālo parku: klintis, senleja, pilis un skatu vietas.',
 'A six-hour guided tour of the Gauja National Park: cliffs, the ancient valley, castles and viewpoints.',
 'Excursión de seis horas por el Parque Nacional del Gauja: acantilados, valle, castillos y miradores.',
 true,4),
('excursion','krimuldas-muiza','krimuldas-muiza','krimuldas-muiza',
 'Krimuldas baznīca, muiža un Gaujas ainavas','Krimulda Church, Manor and Gauja Views','Iglesia y mansión de Krimulda y paisajes del Gauja',
 'Klusākā Gaujas senlejas puse: 13. gadsimta baznīca, klasicisma muiža un skats pāri ielejai.',
 'The quieter side of the Gauja valley: a 13th-century church, a classicist manor and views across the valley.',
 'El lado tranquilo del valle: una iglesia del siglo XIII, una mansión neoclásica y vistas al valle.',
 E'Krimulda ir Siguldas pretējā Gaujas krastā, un tur ir ievērojami klusāk. Sākam pie Krimuldas baznīcas, vienas no vecākajām Latvijā, kuras pirmsākumi meklējami 13. gadsimtā.\n\nTālāk ejam uz Krimuldas muižu — klasicisma ēku ar parku un skatu uz senleju. Stāstu par Lievenu dzimtu un par to, kā muiža kļuva par sanatoriju.\n\nNoslēgumā pastaiga līdz skatu vietām un, ja vēlaties, nobrauciens ar gaisa trošu vagoniņu (nav iekļauts cenā).',
 E'Krimulda lies on the opposite bank from Sigulda and is noticeably quieter. We start at Krimulda Church, one of the oldest in Latvia, with 13th-century origins.\n\nThen the classicist Krimulda Manor with its park and valley views, and the story of the Lieven family.\n\nWe finish at the viewpoints; the cable car ride is optional and not included.',
 E'Krimulda está en la orilla opuesta a Sigulda y es mucho más tranquila. Empezamos en la iglesia, una de las más antiguas de Letonia.\n\nSeguimos con la mansión neoclásica, su parque y las vistas al valle, y la historia de la familia Lieven.\n\nTerminamos en los miradores; el teleférico es opcional.',
 180,30,true,2,8,ARRAY['history','nature']::public.enter_gauja_category[],NULL,'Krimulda',57.1833,24.8333,NULL,NULL,NULL,
 'Krimuldas muiža un baznīca — ekskursija','Krimulda Manor and Church — guided tour','Mansión e iglesia de Krimulda — visita',
 'Trīs stundu ekskursija Krimuldā: viduslaiku baznīca, klasicisma muiža un Gaujas senlejas skati.',
 'A three-hour guided tour in Krimulda: medieval church, classicist manor and Gauja valley views.',
 'Excursión de tres horas en Krimulda: iglesia medieval, mansión neoclásica y vistas del valle.',
 true,5),
('excursion','araisu-ezerpils','araisu-ezerpils','araisu-ezerpils',
 'Āraišu ezerpils un arheoloģiskais parks','Āraiši Lake Fortress and Archaeological Park','Fortaleza lacustre de Āraiši y parque arqueológico',
 'Rekonstruēta 9. gadsimta latgaļu apmetne uz salas un akmens laikmeta mājokļi krastā.',
 'A reconstructed 9th-century Latgalian settlement on an island, with Stone Age dwellings on the shore.',
 'Un asentamiento letgalio del siglo IX reconstruido sobre una isla y viviendas de la Edad de Piedra.',
 E'Āraišu ezerpils ir viena no retajām vietām Eiropā, kur uz ezera salas rekonstruēta 9. gadsimta apmetne tieši tur, kur to atrada arheologi.\n\nEjam pa koka celiņiem starp mājām, skatāmies, kā cilvēki dzīvoja pirms tūkstoš gadiem, un runājam par izrakumiem, kas ilga vairākus gadu desmitus.\n\nKrastā apskatām akmens un bronzas laikmeta mājokļu rekonstrukcijas, viduslaiku pilsdrupas un Āraišu vējdzirnavas.',
 E'Āraiši Lake Fortress is one of the few places in Europe where a 9th-century settlement has been reconstructed on the very island where archaeologists found it.\n\nWe walk the wooden paths between the houses and talk about excavations that lasted decades.\n\nOn the shore we see Stone and Bronze Age reconstructions, the medieval castle ruins and the Āraiši windmill.',
 E'La fortaleza lacustre de Āraiši es uno de los pocos lugares de Europa donde se ha reconstruido un asentamiento del siglo IX en la misma isla donde fue hallado.\n\nRecorremos las pasarelas de madera y hablamos de las excavaciones.\n\nEn la orilla vemos reconstrucciones prehistóricas, las ruinas medievales y el molino de Āraiši.',
 240,40,true,2,8,ARRAY['history','culture']::public.enter_gauja_category[],NULL,'Āraiši',57.2500,25.2833,NULL,NULL,NULL,
 'Āraišu ezerpils — ekskursija ar gidi','Āraiši Lake Fortress — guided tour','Fortaleza lacustre de Āraiši — visita guiada',
 'Četru stundu ekskursija uz Āraišu ezerpili un arheoloģisko parku ar sertificētu gidi.',
 'A four-hour guided tour of the Āraiši Lake Fortress and archaeological park.',
 'Excursión de cuatro horas a la fortaleza lacustre de Āraiši y su parque arqueológico.',
 true,6),
('excursion','zvartes-iezis-amata','zvartes-iezis-amata','zvartes-iezis-amata',
 'Zvārtes iezis un Amatas upes ainavas','Zvārte Rock and the Amata River Landscape','Roca de Zvārte y paisajes del río Amata',
 'Viens no atpazīstamākajiem Latvijas smilšakmens iežiem un taka gar Amatas krastiem.',
 'One of Latvia''s most recognisable sandstone cliffs and a trail along the Amata river.',
 'Uno de los acantilados de arenisca más conocidos de Letonia y un sendero junto al Amata.',
 E'Zvārtes iezis ir 20 metrus augsta smilšakmens klints Amatas upes līkumā — vieta, kur ainava mainās ik pēc dažiem soļiem.\n\nEjam pa taku gar upi, apstājamies pie atsegumiem un runājam par to, kā devona smilšakmens veidojies 350 miljonu gadu laikā, un par teikām, kas ar iezi saistītas.\n\nMaršruts ir daļēji nelīdzens, ar kāpumiem un koka kāpnēm. Ērti apavi nepieciešami.',
 E'Zvārte Rock is a 20-metre sandstone cliff in a bend of the Amata river, where the landscape changes every few steps.\n\nWe follow the riverside trail, stop at the outcrops and talk about Devonian sandstone formed over 350 million years — and the legends attached to the cliff.\n\nThe trail is uneven in places, with climbs and wooden stairs.',
 E'La roca de Zvārte es un acantilado de arenisca de 20 metros en un meandro del Amata.\n\nSeguimos el sendero junto al río, paramos en los afloramientos y hablamos de la arenisca devónica y de las leyendas del lugar.\n\nEl sendero es irregular en tramos, con escaleras de madera.',
 240,40,true,2,8,ARRAY['nature','action']::public.enter_gauja_category[],NULL,'Amata',57.2167,25.1000,NULL,NULL,NULL,
 'Zvārtes iezis un Amata — ekskursija','Zvārte Rock and Amata — guided tour','Roca de Zvārte y Amata — visita guiada',
 'Četru stundu ekskursija pie Zvārtes ieža un pa Amatas upes taku ar gidi.',
 'A four-hour guided tour to Zvārte Rock and along the Amata river trail.',
 'Excursión de cuatro horas a la roca de Zvārte y por el sendero del río Amata.',
 true,7),
-- Hikes
('hiking','gimenes-pargajiens-turaida','gimenes-pargajiens-turaida','gimenes-pargajiens-turaida',
 'Ģimenes pārgājiens Turaidas apkaimē','Family Hike around Turaida','Caminata familiar por los alrededores de Turaida',
 'Viegls maršruts ar bērniem pa mežu takām, avotiem un skatu vietām pie Turaidas.',
 'An easy family route along forest trails, springs and viewpoints near Turaida.',
 'Ruta fácil para familias por senderos, manantiales y miradores cerca de Turaida.',
 E'Maršruts domāts ģimenēm ar bērniem no aptuveni piecu gadu vecuma. Ejam pa mežu takām Turaidas apkaimē, apstājamies pie avotiem un skatu vietām.\n\nPa ceļam runājam par mežu, kokiem un dzīvniekiem tā, lai bērniem ir interesanti: kāpēc priede aug tieši šeit, kā pēc pēdām saprast, kurš ceļu šķērsojis.\n\nTempu nosaka jaunākais dalībnieks. Pārtraukumi tik bieži, cik nepieciešams.',
 E'A route for families with children from around five years old. We walk forest trails around Turaida, stopping at springs and viewpoints.\n\nAlong the way we talk about the forest in a way children enjoy: why a pine grows here, how to read animal tracks.\n\nThe youngest participant sets the pace.',
 E'Ruta para familias con niños desde unos cinco años, por senderos forestales cerca de Turaida.\n\nHablamos del bosque de forma amena: por qué crece aquí ese pino, cómo leer huellas de animales.\n\nEl ritmo lo marca el más pequeño.',
 180,25,true,2,10,ARRAY['nature']::public.enter_gauja_category[],'easy','Turaida',57.1833,24.8500,NULL,NULL,NULL,
 'Ģimenes pārgājiens Turaidā','Family hike in Turaida','Caminata familiar en Turaida',
 'Viegls trīs stundu ģimenes pārgājiens Turaidas mežos ar sertificētu gidi.',
 'An easy three-hour family hike in the Turaida forests with a certified guide.',
 'Caminata familiar fácil de tres horas por los bosques de Turaida con guía certificada.',
 true,8),
('hiking','sigulda-krimulda-pargajiens','sigulda-krimulda-pargajiens','sigulda-krimulda-pargajiens',
 'Gaujas krastu pārgājiens Sigulda–Krimulda','Sigulda–Krimulda Riverside Hike','Caminata Sigulda–Krimulda por la orilla del Gauja',
 'Klasisks senlejas maršruts abos Gaujas krastos ar kāpumiem, alām un tiltu.',
 'The classic valley route on both banks of the Gauja, with climbs, caves and the bridge.',
 'La ruta clásica del valle por ambas orillas, con desniveles, cuevas y el puente.',
 E'Maršruts sākas Siguldā, nolaižas senlejā, šķērso Gauju un kāpj augšā Krimuldas pusē. Kopā apmēram 9 km ar vairākiem kāpumiem.\n\nPa ceļam — Gūtmaņa ala ar avotu, smilšakmens atsegumi, skatu vietas un vecās kāpnes. Stāstu par senlejas veidošanos un par lībiešu laika apmetnēm abos krastos.\n\nNepieciešami ērti apavi un ūdens. Maršruts nav piemērots ratiņiem.',
 E'The route starts in Sigulda, drops into the valley, crosses the Gauja and climbs the Krimulda side — about 9 km with several ascents.\n\nAlong the way: Gūtmanis Cave and its spring, sandstone outcrops, viewpoints and the old stairways.\n\nSturdy shoes and water needed; not suitable for pushchairs.',
 E'La ruta parte de Sigulda, baja al valle, cruza el Gauja y sube por Krimulda: unos 9 km con varios ascensos.\n\nPor el camino: la cueva de Gūtmanis, afloramientos de arenisca y miradores.\n\nSe necesita calzado adecuado y agua.',
 240,30,true,2,10,ARRAY['nature','action']::public.enter_gauja_category[],'medium','Sigulda',57.1626,24.8517,NULL,NULL,NULL,
 'Pārgājiens Sigulda–Krimulda','Sigulda–Krimulda hike','Caminata Sigulda–Krimulda',
 'Vidējas grūtības 9 km pārgājiens pa Gaujas senleju no Siguldas uz Krimuldu.',
 'A moderate 9 km hike through the Gauja valley from Sigulda to Krimulda.',
 'Caminata moderada de 9 km por el valle del Gauja, de Sigulda a Krimulda.',
 true,9),
('hiking','zvartes-amata-pargajiens','zvartes-amata-pargajiens','zvartes-amata-pargajiens',
 'Zvārtes ieža un Amatas krastu pārgājiens','Zvārte Rock and Amata Riverside Hike','Caminata por la roca de Zvārte y el Amata',
 'Piecas stundas gar Amatas upi: iezis, straujteces un meža takas bez pūļa.',
 'Five hours along the Amata: the cliff, rapids and forest trails without the crowds.',
 'Cinco horas junto al Amata: el acantilado, rápidos y senderos sin multitudes.',
 E'Amatas taka ir viens no skaistākajiem maršrutiem Gaujas Nacionālajā parkā, īpaši pavasarī un rudenī. Ejam gar upi, kur straume ir ātra un krasti stāvi.\n\nGalvenais punkts — Zvārtes iezis, bet ceļā ir vēl vairāki mazāk zināmi atsegumi un pārbrišanas vietas.\n\nMaršruts vidējas grūtības, apmēram 10 km, ar nelīdzenu segumu. Nepieciešami stingri apavi.',
 E'The Amata trail is one of the finest routes in the Gauja National Park, especially in spring and autumn, following a fast river between steep banks.\n\nThe highlight is Zvārte Rock, but there are several lesser-known outcrops and fords on the way.\n\nModerate, about 10 km on uneven ground. Firm footwear required.',
 E'El sendero del Amata es de los más bellos del parque, sobre todo en primavera y otoño, junto a un río rápido entre orillas escarpadas.\n\nEl punto principal es la roca de Zvārte, con otros afloramientos y vados en el camino.\n\nDificultad media, unos 10 km.',
 300,35,true,2,10,ARRAY['nature','action']::public.enter_gauja_category[],'medium','Amata',57.2167,25.1000,NULL,NULL,NULL,
 'Amatas takas pārgājiens ar gidi','Amata trail guided hike','Caminata guiada por el sendero del Amata',
 'Piecu stundu pārgājiens pa Amatas taku līdz Zvārtes iezim sertificētas gides pavadībā.',
 'A five-hour guided hike along the Amata trail to Zvārte Rock.',
 'Caminata guiada de cinco horas por el sendero del Amata hasta la roca de Zvārte.',
 true,10),
('hiking','ligatnes-dabas-takas','ligatnes-dabas-takas','ligatnes-dabas-takas',
 'Līgatnes dabas takas — pilna diena','Līgatne Nature Trails — Full Day','Senderos naturales de Līgatne — día completo',
 'Sešas stundas mežā: dabas takas, savvaļas dzīvnieku aploki un Gaujas krasts.',
 'Six hours in the forest: nature trails, wildlife enclosures and the Gauja riverside.',
 'Seis horas en el bosque: senderos, recintos de fauna y la orilla del Gauja.',
 E'Līgatnes dabas takas ir plaša mežu teritorija ar takām, skatu torņiem un aplokiem, kur redzami Latvijas savvaļas dzīvnieki — aļņi, staltbrieži, lūši, lapsas.\n\nDienas laikā izejam garo loku, apstājamies pie aplokiem un skatu torņa, un noslēgumā nokāpjam pie Gaujas.\n\nMaršruts garš, bet bez smagiem kāpumiem. Līdzi ņemam pusdienas un ūdeni.',
 E'The Līgatne nature trails cover a large forest area with paths, viewing towers and enclosures where Latvian wildlife can be seen — elk, red deer, lynx, foxes.\n\nWe walk the long loop, stop at the enclosures and the tower, and finish by the Gauja.\n\nLong but without hard climbs. Bring lunch and water.',
 E'Los senderos de Līgatne recorren un gran bosque con torres de observación y recintos con fauna letona: alces, ciervos, linces, zorros.\n\nHacemos el circuito largo y terminamos junto al Gauja.\n\nLargo pero sin ascensos duros. Traer comida y agua.',
 360,45,true,2,10,ARRAY['nature']::public.enter_gauja_category[],'medium','Līgatne',57.2333,25.0500,NULL,NULL,NULL,
 'Līgatnes dabas takas — pilnas dienas pārgājiens','Līgatne nature trails — full day hike','Senderos de Līgatne — caminata de día completo',
 'Sešu stundu pārgājiens pa Līgatnes dabas takām ar savvaļas dzīvnieku aplokiem.',
 'A six-hour hike along the Līgatne nature trails with wildlife enclosures.',
 'Caminata de seis horas por los senderos de Līgatne con recintos de fauna.',
 true,11),
('hiking','cesu-mezi-ezeri','cesu-mezi-ezeri','cesu-mezi-ezeri',
 'Cēsu apkaimes meži un ezeri','Forests and Lakes around Cēsis','Bosques y lagos de los alrededores de Cēsis',
 'Mierīgs maršruts pa priežu mežiem un ezeru krastiem netālu no Cēsīm.',
 'A calm route through pine forests and along lake shores near Cēsis.',
 'Ruta tranquila por pinares y orillas de lagos cerca de Cēsis.',
 E'Ap Cēsīm ir vairāki nelieli ezeri, pie kuriem tūristi nonāk reti. Ejam pa priežu mežu takām, apstājamies pie Cīrulīšu dabas takām un ezera krasta.\n\nMaršruts viegls, bez stāviem kāpumiem, piemērots arī tiem, kas pārgājienos iet reti.\n\nVasarā iespējama peldēšanās, rudenī — sēņošana un ogošana.',
 E'There are several small lakes around Cēsis that tourists rarely reach. We walk pine forest trails, stopping at the Cīrulīši nature trails and the lake shore.\n\nEasy, with no steep climbs — suitable for occasional walkers.\n\nSwimming in summer, mushroom and berry picking in autumn.',
 E'Cerca de Cēsis hay varios lagos poco visitados. Caminamos por pinares y paramos en los senderos de Cīrulīši y en la orilla.\n\nFácil, sin ascensos pronunciados.\n\nEn verano se puede nadar; en otoño, recoger setas.',
 240,30,true,2,10,ARRAY['nature']::public.enter_gauja_category[],'easy','Cēsis',57.3119,25.2749,NULL,NULL,NULL,
 'Pārgājiens Cēsu mežos un pie ezeriem','Hike in the forests and lakes of Cēsis','Caminata por bosques y lagos de Cēsis',
 'Viegls četru stundu pārgājiens pa Cēsu apkaimes priežu mežiem un ezeru krastiem.',
 'An easy four-hour hike through pine forests and lake shores around Cēsis.',
 'Caminata fácil de cuatro horas por pinares y lagos cerca de Cēsis.',
 true,12),
('hiking','gaujas-np-dienas-marsruts','gaujas-np-dienas-marsruts','gaujas-np-dienas-marsruts',
 'Gaujas NP dienas maršruts','Gauja NP Full-Day Route','Ruta de día completo por el Parque Nacional',
 'Astoņas stundas un ap 20 km pa mazāk zināmām parka takām pieredzējušiem gājējiem.',
 'Eight hours and about 20 km on the park''s lesser-known trails, for experienced walkers.',
 'Ocho horas y unos 20 km por senderos poco conocidos, para caminantes experimentados.',
 E'Garākais maršruts manā piedāvājumā — apmēram 20 km pa Gaujas Nacionālā parka takām, kuras nav norādītas standarta kartēs.\n\nEjam pa senlejas malām, meža ceļiem un upju krastiem, ar vairākiem kāpumiem un nolaišanās posmiem. Apstāšanās pie atsegumiem un skatu vietām.\n\nPiemērots tikai tiem, kas regulāri staigā. Nepieciešami pārgājienu apavi, ūdens vismaz 1,5 l un pusdienas līdzi.',
 E'The longest route I offer — about 20 km on Gauja National Park trails that are not on standard maps.\n\nWe follow valley edges, forest roads and riverbanks, with several ascents and descents, stopping at outcrops and viewpoints.\n\nOnly for regular walkers. Hiking boots, at least 1.5 l of water and a packed lunch required.',
 E'La ruta más larga que ofrezco: unos 20 km por senderos que no aparecen en los mapas habituales.\n\nBordes del valle, caminos forestales y orillas, con varios desniveles.\n\nSolo para caminantes habituales. Botas, 1,5 l de agua y comida.',
 480,60,true,2,10,ARRAY['nature','action']::public.enter_gauja_category[],'hard','Gaujas Nacionālais parks',57.2500,25.0000,NULL,NULL,NULL,
 'Gaujas NP dienas pārgājiens','Gauja NP full-day hike','Caminata de día completo en el Parque del Gauja',
 'Astoņu stundu, 20 km pārgājiens pa Gaujas Nacionālā parka mazāk zināmajām takām.',
 'An eight-hour, 20 km hike on the lesser-known trails of the Gauja National Park.',
 'Caminata de ocho horas y 20 km por los senderos menos conocidos del parque.',
 true,13),
('hiking','vakara-pargajiens-saulriets','vakara-pargajiens-saulriets','vakara-pargajiens-saulriets',
 'Vakara pārgājiens ar saulrieta izbaudīšanu','Evening Hike with Sunset','Caminata vespertina con puesta de sol',
 'Trīs stundas vakara gaismā līdz skatu vietai, kur saule noriet pāri senlejai.',
 'Three hours in evening light to a viewpoint where the sun sets over the valley.',
 'Tres horas con luz vespertina hasta un mirador sobre el valle.',
 E'Izejam pāris stundas pirms saulrieta un ejam mierīgā tempā uz skatu vietu senlejas malā.\n\nVakarā mežs skan citādi, gaisma maina ainavu ik pēc dažām minūtēm, un cilvēku takās gandrīz nav. Pa ceļam runājam par vietas stāstiem un vakara dabu.\n\nLīdzi ņemam siltāku jaku un lukturīti atpakaļceļam. Maršruts viegls.',
 E'We set out a couple of hours before sunset and walk at a calm pace to a viewpoint on the edge of the valley.\n\nThe forest sounds different in the evening, the light changes the landscape every few minutes and the trails are almost empty.\n\nBring a warm jacket and a torch for the way back. Easy route.',
 E'Salimos un par de horas antes del atardecer hacia un mirador en el borde del valle.\n\nEl bosque suena distinto al anochecer y los senderos están casi vacíos.\n\nLleve chaqueta y linterna. Ruta fácil.',
 180,30,true,2,10,ARRAY['nature','culture']::public.enter_gauja_category[],'easy','Sigulda',57.1626,24.8517,NULL,NULL,NULL,
 'Vakara pārgājiens ar saulrietu Siguldā','Evening sunset hike in Sigulda','Caminata al atardecer en Sigulda',
 'Viegls trīs stundu vakara pārgājiens ar saulrietu Gaujas senlejas skatu vietā.',
 'An easy three-hour evening hike with sunset over the Gauja valley.',
 'Caminata fácil de tres horas al atardecer sobre el valle del Gauja.',
 true,14),
