-- ===== FAQ =====
INSERT INTO public.faq (question_lv, question_en, question_es, answer_lv, answer_en, answer_es, category, sort_order, is_active) VALUES
('Kā rezervēt ekskursiju vai pārgājienu?','How do I book a tour or hike?','¿Cómo reservo una excursión o caminata?',
 'Aizpildiet rezervācijas formu mājaslapā vai rakstiet e-pastā. Atbildu 24 stundu laikā ar apstiprinājumu vai alternatīvu laiku.',
 'Fill in the booking form on the website or send an email. I reply within 24 hours with a confirmation or an alternative time.',
 'Rellene el formulario de reserva o escriba un correo. Respondo en 24 horas con la confirmación o una alternativa.','booking',1,true),
('Kādās valodās notiek ekskursijas?','In which languages are the tours held?','¿En qué idiomas se realizan las excursiones?',
 'Latviski, angliski, krieviski un spāniski. Valodu norādiet rezervācijā.',
 'In Latvian, English, Russian and Spanish. Please state your language when booking.',
 'En letón, inglés, ruso y español. Indique el idioma al reservar.','practical',2,true),
('Kas jāņem līdzi pārgājienā?','What should I bring on a hike?','¿Qué debo llevar a una caminata?',
 'Ērti, aizsegti apavi, laikapstākļiem piemērots apģērbs, ūdens un neliela uzkoda. Garākos maršrutos — vismaz 1,5 l ūdens un pusdienas.',
 'Comfortable closed shoes, clothing suited to the weather, water and a snack. On longer routes at least 1.5 l of water and a packed lunch.',
 'Calzado cerrado y cómodo, ropa adecuada al tiempo, agua y algo de comer. En rutas largas, 1,5 l de agua y comida.','practical',3,true),
('Vai ekskursijas notiek sliktos laikapstākļos?','Do tours run in bad weather?','¿Las excursiones se realizan con mal tiempo?',
 'Jā, lietus vai sniegs nav šķērslis — pielāgojam maršrutu. Atceļam tikai bīstamos apstākļos, piemēram, vētrā; tādā gadījumā piedāvāju citu datumu vai atmaksu.',
 'Yes — rain or snow is not an obstacle and the route is adapted. I only cancel in dangerous conditions such as storms, offering another date or a refund.',
 'Sí; la lluvia o la nieve no son un obstáculo y adaptamos la ruta. Solo cancelo con condiciones peligrosas, ofreciendo otra fecha o reembolso.','practical',4,true),
('Vai cenā ir iekļautas pusdienas?','Are meals included in the price?','¿La comida está incluida?',
 'Nē, ēdināšana nav iekļauta. Garākos maršrutos iesaku ņemt līdzi pusdienas; ekskursijās pilsētās varu ieteikt vietējās kafejnīcas.',
 'No, meals are not included. On longer routes bring a packed lunch; on town tours I can recommend local cafés.',
 'No, la comida no está incluida. En rutas largas lleve comida; en las visitas urbanas puedo recomendar cafeterías.','pricing',5,true),
('Kā atcelt vai pārcelt rezervāciju?','How do I cancel or reschedule a booking?','¿Cómo cancelo o cambio una reserva?',
 'Rakstiet man vismaz 48 stundas iepriekš — pārcelšana vai atcelšana ir bez maksas. Vēlāk atcelšanas gadījumā var tikt piemērota daļēja maksa.',
 'Write to me at least 48 hours in advance — rescheduling or cancelling is free. Later cancellations may incur a partial charge.',
 'Escríbame con al menos 48 horas de antelación: cambiar o cancelar es gratuito. Después puede aplicarse un cargo parcial.','booking',6,true),
('Vai vienā dienā var apvienot vairākas ekskursijas?','Can several tours be combined in one day?','¿Se pueden combinar varias excursiones en un día?',
 'Jā. Populārākais variants ir Sigulda un Turaida no rīta un Cēsis pēcpusdienā. Uzrakstiet, ko vēlaties redzēt, un salikšu reālu dienas plānu.',
 'Yes. The most popular combination is Sigulda and Turaida in the morning and Cēsis in the afternoon. Tell me what you want to see and I will put together a realistic plan.',
 'Sí. La combinación más habitual es Sigulda y Turaida por la mañana y Cēsis por la tarde. Dígame qué quiere ver y prepararé un plan realista.','booking',7,true),
('Vai bērniem ir atlaides?','Are there discounts for children?','¿Hay descuentos para niños?',
 'Bērniem līdz 7 gadu vecumam dalība ir bez maksas, no 7 līdz 14 gadiem — puse no cenas par personu. Transfēros cena ir par braucienu, tāpēc bērnu skaits cenu nemaina.',
 'Children under 7 join free of charge, from 7 to 14 pay half the per-person price. Transfers are priced per ride, so the number of children does not change the price.',
 'Los menores de 7 años no pagan; de 7 a 14 años, la mitad del precio por persona. Los traslados se cobran por trayecto.','pricing',8,true),
('Vai transfērs pieejams agri no rīta vai vēlu vakarā?','Is a transfer available early in the morning or late at night?','¿Hay traslados de madrugada o de noche?',
 'Jā, braucu arī agros rītos un vēlos vakaros, tostarp uz lidostu. Laiku ārpus 7.00–22.00 lūdzu saskaņot vismaz dienu iepriekš.',
 'Yes, I drive early mornings and late evenings, including airport runs. Please arrange times outside 07:00–22:00 at least a day ahead.',
 'Sí, conduzco de madrugada y por la noche, también al aeropuerto. Fuera del horario 07:00–22:00, avise con un día de antelación.','practical',9,true),
('Kā notiek apmaksa?','How does payment work?','¿Cómo se realiza el pago?',
 'Maksāt var skaidrā naudā tikšanās vietā vai ar pārskaitījumu pēc rēķina. Priekšapmaksa nav nepieciešama, izņemot lielas grupas un garos transfērus.',
 'You can pay in cash at the meeting point or by bank transfer against an invoice. No prepayment is required except for large groups and long transfers.',
 'Puede pagar en efectivo en el punto de encuentro o por transferencia con factura. No se requiere pago anticipado salvo grupos grandes y traslados largos.','pricing',10,true)
ON CONFLICT DO NOTHING;